const scenarioText={constant:'Constant conditions for the five-stage ablation study.',irradiance:'Irradiance changes at the selected event iteration.',rapid:'Five equal segments: G × [1, 0.5, 0.8, 0.3, 0.9].',temperature:'Cell temperature changes at the selected event iteration.',load:'Load resistance changes at the selected event iteration.',burst:'Reproducible 8 W measurement-noise burst over iterations 150–399.',shading:'Three substrings become unequally illuminated at the event.',trap:'Shading from startup, with duty 0.65 initially near a local-peak basin.'};
function control(key,label,min,max,step,unit,container){let el=document.createElement('div');el.className='control';el.innerHTML=`<div class="control-top"><label for="number-${key}">${label}</label><div class="number-wrap"><input id="number-${key}" type="number" min="${min}" max="${max}" step="${step}" aria-label="${label}"><span>${unit}</span></div></div><input type="range" min="${min}" max="${max}" step="${step}" aria-label="${label} slider">`;let [number,range]=el.querySelectorAll('input');number.value=Number(options[key].toFixed(6));range.value=options[key];number.addEventListener('change',()=>{let value=Number(number.value);if(!Number.isFinite(value))value=defaults[key];value=Math.min(max,Math.max(min,value));if(key==='enter')value=Math.max(value,options.exit+.05);if(key==='exit')value=Math.min(value,options.enter-.05);options[key]=value;number.value=value;range.value=value;queue()});range.addEventListener('input',()=>{options[key]=+range.value;if(key==='enter')options[key]=Math.max(options[key],options.exit+.05);if(key==='exit')options[key]=Math.min(options[key],options.enter-.05);number.value=options[key];range.value=options[key];queue()});$(container).appendChild(el)}
function buildControls(){ $('#controls').innerHTML='';$('#advanced').innerHTML='';control('G','Irradiance',100,1200,10,'W/m²','#controls');control('T','Cell temperature',0,70,1,'°C','#controls');control('R','Load resistance',5,40,.1,'Ω','#controls');control('D0','Initial duty',.1,.8,.01,'','#controls');if(options.scenario!=='burst')control('noise','Power noise σ',0,8,.1,'W','#controls');control('seed','Noise seed',0,7,1,'','#controls');if(['irradiance','temperature','load','shading'].includes(options.scenario)){control('event','Event iteration',10,options.N-10,1,'','#controls');if(options.scenario==='irradiance')control('G2','Irradiance after event',100,1200,10,'W/m²','#controls');if(options.scenario==='temperature')control('T2','Temperature after event',0,70,1,'°C','#controls');if(options.scenario==='load')control('R2','Load after event',5,40,.1,'Ω','#controls')}
if(['shading','trap'].includes(options.scenario)){control('shade2','Substring 2 irradiance',.1,1,.05,'× G','#controls');control('shade3','Substring 3 irradiance',.1,1,.05,'× G','#controls')}
control('step','P&O fixed step',.001,.03,.001,'','#advanced');control('eta','RLS ascent gain η',.00001,.0002,.00001,'','#advanced');control('lam','RLS forgetting factor λ',.4,.98,.01,'','#advanced');control('enter','HOLD entry confidence',.5,.95,.05,'','#advanced');control('exit','HOLD exit confidence',.1,.5,.05,'','#advanced');control('search','SEARCH confidence',.05,.3,.01,'','#advanced');control('persistence','SEARCH persistence',10,100,1,'steps','#advanced');}
function queue(){simulationPending=true;clearTimeout(pending);requestId++;stop();$('#run-status').textContent='Recalculating…';$('#export').disabled=true;$('#export-settings').disabled=true;pending=setTimeout(run,180)}
function run(){simulationPending=true;requestId++;$('#run-status').classList.remove('error');$('#run-status').textContent='Solving PV operating points…';worker.postMessage({id:requestId,options:{...options}})}
function onResult(m){if(m.id!==requestId)return;if(m.error){$('#run-status').textContent='Model error: '+m.error;$('#run-status').classList.add('error');return}simulationPending=false;runs=m.runs;scores=m.metrics;lastReference=m.isReference;cursor=Math.min(cursor,options.N-1);$('#cursor').max=options.N-1;$('#cursor').value=cursor;$('#run-status').textContent=m.isReference?'Report preset · original Python traces':'Live recomputation · seed '+options.seed;$('#export').disabled=false;completedOptions={...options};$('#export-settings').disabled=false;render();}
function tabs(){ $('#controller-tabs').innerHTML=names.map((n,i)=>`<button data-controller="${i}" class="${i===selected?'selected':''}" aria-pressed="${i===selected}"><i style="background:${colors[i]}"></i>${n}</button>`).join('');$$('[data-controller]').forEach(b=>b.onclick=()=>{selected=+b.dataset.controller;tabs();render()})}
function changeView(v){view=v;stop();$('#workspace').hidden=!['lab','full'].includes(v);$('#report-view').hidden=v!=='report';$('#converter-view').hidden=v!=='converter';$('#evidence-view').hidden=v!=='evidence';$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='report'){if(reference){reportTable();showFigure()}return}if(v==='converter'){runBoost();return}if(v==='evidence'){renderBenchmark();return}if(v==='full'){selected=4;$('#compare').checked=false}$('#controller-tabs').hidden=v==='full';$('#full-detail').hidden=v!=='full';$('#eyebrow').textContent=v==='full'?'EXPERIMENT 02 / CONFIDENCE-AWARE CONTROL':'EXPERIMENT 01 / CONTROLLER COMPARISON';$('#view-title').textContent=v==='full'?'Track. Hold. Search when needed.':'Small changes. Measurable response.';$('#view-description').textContent=v==='full'?'Follow the estimated slope, confidence and state transitions of the complete controller.':'Explore how five MPPT stages find and hold the maximum power point.';tabs();render()}
function render(){if(simulationPending||!runs||!['lab','full'].includes(view))return;let row=runs[selected][cursor],m=scores[selected];$('#metrics').innerHTML=`<div><span>Tracking efficiency</span><strong>${m.eta.toFixed(2)}<small>%</small></strong></div><div><span>Steady-state efficiency</span><strong>${m.ss.toFixed(2)}<small>%</small></strong></div><div><span>Activity index</span><strong>${m.activity.toFixed(3)}</strong></div><div><span>Duty oscillation</span><strong>${m.osc===0?'0.0000':m.osc.toFixed(5)}</strong></div>`;$('#pv-v').textContent=row.V.toFixed(3)+' V';$('#pv-i').textContent=row.I.toFixed(3)+' A';$('#out-v').textContent=(row.V/(1-row.Dused)).toFixed(3)+' V';$('#d-used').textContent=row.Dused.toFixed(5);$('#controller-label').textContent=names[selected];$('#cursor-value').textContent=cursor;$('#state').textContent=row.stateUsed;$('#state').style.background=row.stateUsed==='HOLD'?'#e6f2ec':row.stateUsed==='SEARCH'?'#faede0':'#e9f1f5';$('#state').style.color=row.stateUsed==='HOLD'?'#467b61':row.stateUsed==='SEARCH'?'#a6682d':'#1c627b';$('#slope-readout').textContent='dP/dD = '+(row.theta_hat??0).toFixed(3)+' W/duty';$$('[data-state]').forEach(el=>el.classList.toggle('current',el.dataset.state===row.stateUsed));let transitions=runs[selected].filter((r,i)=>i&&r.state!==runs[selected][i-1].state).map(r=>`${r.k}: ${r.state}`);$('#transition-log').textContent=transitions.length?'Transitions (iteration → new state): '+transitions.join(' · '):'No state transitions during this run.';$('#model-note').textContent=(lastReference?'Original Python baseline. ':'Browser recomputation of the project equations. ')+'Algorithm-level, quasi-static model · iterations are not seconds · tracking efficiency is not converter efficiency.';renderLiveComparison();draw();}
function graph(id,series,{yMin=null,yMax=null,xMin=0,xMax=options.N-1,cursorAt=cursor,xLabel='Iteration',dot=null,interactive=true}={}){let canvas=$(id),width=canvas.clientWidth;if(!width)return;let height=Number(canvas.getAttribute('height'))/(canvas.dataset.scaled?devicePixelRatio:1);height=+canvas.dataset.height||height;canvas.dataset.height=height;let ratio=window.devicePixelRatio||1;canvas.width=width*ratio;canvas.height=height*ratio;canvas.style.height=height+'px';canvas.dataset.scaled='1';let ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);let l=49,r=18,t=12,b=37,w=width-l-r,h=height-t-b;let vals=series.flatMap(s=>s.data.map(p=>p[1])).filter(Number.isFinite);let lo=yMin??Math.min(...vals),hi=yMax??Math.max(...vals);if(yMin===null||yMax===null){let pad=Math.max((hi-lo)*.1,.005);if(yMin===null)lo-=pad;if(yMax===null)hi+=pad}if(hi===lo)hi=lo+1;let X=x=>l+(x-xMin)/(xMax-xMin)*w,Y=y=>t+(hi-y)/(hi-lo)*h;ctx.font='12px Arial';ctx.textBaseline='middle';for(let i=0;i<5;i++){let y=lo+(hi-lo)*i/4,py=Y(y);ctx.strokeStyle='#edf1f4';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(l,py);ctx.lineTo(width-r,py);ctx.stroke();ctx.fillStyle='#8797a1';ctx.textAlign='right';ctx.fillText(Math.abs(y)>=100?y.toFixed(0):Math.abs(hi-lo)<.1?y.toFixed(3):Math.abs(hi-lo)<2?y.toFixed(2):y.toFixed(0),l-9,py)}for(let i=0;i<6;i++){let x=xMin+(xMax-xMin)*i/5;ctx.textAlign='center';ctx.fillStyle='#8797a1';ctx.fillText(xMax<1?x.toFixed(2):Math.round(x),X(x),height-23)}ctx.fillStyle='#95a2ab';ctx.textAlign='right';ctx.font='11px Arial';ctx.fillText(xLabel,width-r,height-8);ctx.save();ctx.beginPath();ctx.rect(l,t,w,h);ctx.clip();for(let s of series){ctx.beginPath();ctx.strokeStyle=s.color;ctx.lineWidth=s.width||1.6;ctx.setLineDash(s.dash||[]);s.data.forEach(([x,y],i)=>{if(i)ctx.lineTo(X(x),Y(y));else ctx.moveTo(X(x),Y(y))});ctx.stroke()}ctx.setLineDash([]);if(cursorAt!==null){ctx.strokeStyle='#b0bdc5';ctx.lineWidth=1;ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(X(cursorAt),t);ctx.lineTo(X(cursorAt),t+h);ctx.stroke();ctx.setLineDash([])}if(dot){ctx.beginPath();ctx.arc(X(dot[0]),Y(dot[1]),4,0,Math.PI*2);ctx.fillStyle=colors[selected];ctx.fill();ctx.strokeStyle='white';ctx.lineWidth=2;ctx.stroke()}ctx.restore();canvas.onclick=e=>{if(interactive&&xMax>1){let rect=canvas.getBoundingClientRect();cursor=Math.max(0,Math.min(options.N-1,Math.round((e.clientX-rect.left-l)/w*(xMax-xMin)+xMin)));$('#cursor').value=cursor;render()}}}
function draw(){if(view==='converter'){drawBoost();return}if(simulationPending||!runs||!['lab','full'].includes(view))return;let all=$('#compare').checked,ids=all?[0,1,2,3,4]:[selected],rows=runs[selected],r=rows[cursor];let series=key=>ids.map(i=>({color:colors[i],width:i===selected?2:1.2,data:runs[i].map((r,k)=>[k,r[key]])}));let ps=series('P');ps.push({color:'#bbc5cc',dash:[4,4],data:rows.map((r,k)=>[k,r.pmpp])});$('#legend').innerHTML=ids.map(i=>`<span><i style="background:${colors[i]}"></i>${names[i]}</span>`).join('')+'<span><i style="background:#bbc5cc"></i>MPP reference</span>';graph('#power-chart',ps,{yMin:0,dot:[cursor,r.P]});graph('#duty-chart',series('D'),{dot:[cursor,r.D]});let hasConf=selected>=3;$('#secondary-title').textContent=hasConf?'Confidence':selected===2?'Estimated slope':'Instantaneous tracking';$('#secondary-unit').textContent=hasConf?'0–1':selected===2?'W/duty':'%';let key=hasConf?'confidence':'theta_hat';let data=rows.map((r,k)=>[k,hasConf?r.confidence:selected===2?r.theta_hat:100*r.P/r.pmpp]);let ss=[{color:colors[selected],data}];if(hasConf){ss.push({color:'#74a390',dash:[4,4],data:[[0,options.enter],[options.N-1,options.enter]]},{color:'#c3a176',dash:[4,4],data:[[0,options.exit],[options.N-1,options.exit]]});if(selected===4)ss.push({color:'#c28c88',dash:[2,4],data:[[0,options.search],[options.N-1,options.search]]})}graph('#confidence-chart',ss,{yMin:hasConf?0:null,yMax:hasConf?1:null,dot:[cursor,data[cursor][1]]});let curve=Array.from({length:181},(_,i)=>{let d=.1+.7*i/180;return [d,plant.point(d,r.G,r.T,r.R,r.shade).P]});graph('#curve-chart',[{color:'#92a9b5',data:curve,width:1.8}],{xMin:.1,xMax:.8,yMin:0,cursorAt:null,xLabel:'Applied duty D',dot:[r.Dused,r.P]});}
function setPhase(p){phase=p;$$('[data-phase]').forEach(b=>b.classList.toggle('chosen',b.dataset.phase===p));$('#switch-blade').setAttribute('d',p==='on'?'M210 118V151':'M210 118L224 146');$('#switch-blade').setAttribute('stroke',p==='on'?'#b96c32':'#354552');$('#switch-blade').setAttribute('stroke-width',p==='on'?'3':'1.8');$('#phase-note').textContent={average:'Steady-state readings at the selected iteration. Switch phases illustrate topology; ripple is not simulated.',on:'Q closed: PV supplies the inductor; the diode is reverse biased and Cout supplies the load. vL = Vpv, iC = −Vout/R. Readings remain cycle averages.',off:'Q open: PV and the inductor supply the output through the diode. vL = Vpv − Vout, iC = iL − Vout/R. Readings remain cycle averages.'}[p]}
function stop(){clearInterval(playing);playing=null;$('#play').textContent='▶ Play'}
function reset(){options={...defaults};$('#scenario').value='constant';$('#scenario-desc').textContent=scenarioText.constant;cursor=499;buildControls();queue()}
function selectScenario(){let s=$('#scenario').value;options={...options,scenario:s,N:['burst','trap'].includes(s)?600:500,D0:s==='trap'?.65:.2,event:s==='shading'?200:250};if(s==='burst')options.noise=0;cursor=options.N-1;$('#scenario-desc').textContent=scenarioText[s];buildControls();queue()}
function reportTable(){let noisy=$('#report-scenario').value;$('#report-table').innerHTML=reference.table.filter(r=>r.scenario===noisy).map((r,i)=>`<tr><td><span style="color:${colors[i]}">${r.controller}</span></td><td>${(+r.eta_full*100).toFixed(2)}%</td><td>${(+r.eta_ss*100).toFixed(2)}%</td><td>${(+r.activity_index).toFixed(3)}</td><td>${(+r.osc).toFixed(6)}</td></tr>`).join('')}
function showFigure(){let f=figs[+$('#figure-select').value];$('#report-figure').src='data/figures/'+f[0];$('#report-figure').alt=f[1];$('#figure-link').href='data/figures/'+f[0];$('#figure-caption').textContent=f[2]}
function exportCSV(){if(!runs)return;let header='controller,iteration,G_W_m2,T_C,R_ohm,D_applied,D_next,Vpv_V,Ipv_A,Ppv_W,Vout_ideal_V,MPP_reference_W,confidence,slope_W_per_duty,state_applied,state_next,perturbed';let text=header+'\n'+runs.flatMap((rows,i)=>rows.map(r=>[names[i],r.k,r.G,r.T,r.R,r.Dused,r.D,r.V,r.I,r.P,r.V/(1-r.Dused),r.pmpp,r.confidence??'',r.theta_hat??'',r.stateUsed,r.state,+r.perturbed].join(','))).join('\n');let url=URL.createObjectURL(new Blob([text],{type:'text/csv'}));let a=document.createElement('a');a.href=url;a.download='mppt-'+options.scenario+'-seed-'+options.seed+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$$('.nav').forEach(b=>b.onclick=()=>changeView(b.dataset.view));$$('[data-phase]').forEach(b=>b.onclick=()=>setPhase(b.dataset.phase));$('#reset').onclick=reset;$('#export').onclick=exportCSV;$('#scenario').onchange=selectScenario;$('#compare').onchange=draw;$('#cursor').oninput=()=>{cursor=+$('#cursor').value;render()};$('#play').onclick=()=>{if(playing)return stop();if(cursor>=options.N-1)cursor=0;$('#play').textContent='Ⅱ Pause';playing=setInterval(()=>{cursor=Math.min(options.N-1,cursor+2);$('#cursor').value=cursor;render();if(cursor===options.N-1)stop()},70)};$('#report-scenario').onchange=reportTable;$('#figure-select').innerHTML=figs.map((f,i)=>`<option value="${i}">${f[1]}</option>`).join('');$('#figure-select').onchange=showFigure;
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(draw,100)});
async function init(){try{let response=await fetch('data/reference.json');if(!response.ok)throw Error('Could not load project data');reference=await response.json();$('#benchmark-run').disabled=false;plant=new Plant(reference.stc);worker=new Worker('worker.js',{type:'module'});worker.onerror=()=>{$('#run-status').textContent='Simulation could not start. Reload this page.';$('#run-status').classList.add('error')};worker.onmessage=e=>onResult(e.data);worker.postMessage({init:reference});buildControls();tabs();run();registerTools()}catch(e){$('#run-status').textContent=e.message;$('#run-status').classList.add('error')}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const abort=new AbortController();window.addEventListener('pagehide',()=>abort.abort(),{once:true});Promise.resolve(context.registerTool({name:'configure_mppt_experiment',title:'Configure MPPT experiment',description:'Change the visible MPPT experiment and recompute all five controllers.',inputSchema:{type:'object',properties:{irradiance:{type:'number',minimum:100,maximum:1200},temperature:{type:'number',minimum:0,maximum:70},load:{type:'number',minimum:5,maximum:40},scenario:{type:'string',enum:Object.keys(scenarioText)}},additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['irradiance','temperature','load','scenario'].includes(k)))throw Error('Invalid configuration');for(let [key,min,max] of [['irradiance',100,1200],['temperature',0,70],['load',5,40]])if(key in input&&(typeof input[key]!=='number'||!Number.isFinite(input[key])||input[key]<min||input[key]>max))throw Error('Invalid '+key);if('scenario'in input&&!Object.keys(scenarioText).includes(input.scenario))throw Error('Invalid scenario');if(input.irradiance!==undefined)options.G=input.irradiance;if(input.temperature!==undefined)options.T=input.temperature;if(input.load!==undefined)options.R=input.load;if(input.scenario){$('#scenario').value=input.scenario;selectScenario()}else{buildControls();queue()}changeView('lab');await new Promise((resolve,reject)=>{const target=requestId+1;const listener=e=>{if(e.data.id>=target){worker.removeEventListener('message',listener);e.data.error?reject(Error(e.data.error)):resolve()}};worker.addEventListener('message',listener)});return {scenario:options.scenario,fullController:scores[4]}}},{signal:abort.signal})).catch(()=>{});}
init();
let completedOptions=null,benchResult=null,benchWorker=null,boostResult=null;
function downloadFile(name,text,type='application/json'){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function renderLiveComparison(){let event=['irradiance','temperature','load','shading'].includes(options.scenario)?options.event:0;$('#live-table').innerHTML=scores.map((m,i)=>{let acquired=recovery(runs[i],event);return `<tr class="${i===selected?'comparison-selected':''}"><td>${names[i]}</td><td>${m.eta.toFixed(2)}%</td><td>${m.activity.toFixed(3)}</td><td>${acquired===null?'Not reached':acquired+' iterations'}</td><td>${m.osc.toFixed(5)}</td></tr>`}).join('');let full=scores[4],base=scores[0],change=full.eta-base.eta,reduction=(1-full.activity/base.activity)*100;$('#comparison-insight').textContent=`Full controller vs P&O: ${change>=0?'+':''}${change.toFixed(2)} percentage points of full-run tracking efficiency; ${reduction.toFixed(1)}% fewer active perturbation samples. This is not a switching-loss measurement.`;let audits=runs.map(auditRun),balance=Math.max(...audits.map(a=>a.maxBalance)),margin=Math.min(...audits.map(a=>a.minCCMMargin));let checks=[[audits.every(a=>a.finite),'Finite voltage, current, power and duty'],[audits.every(a=>a.bounded),'Applied and next duty within 0.10–0.80'],[balance<1e-5,`Ideal power balance error ≤ ${balance.toExponential(1)} W`],[margin>0,`Steady-state CCM load margin ≥ ${margin.toFixed(1)} Ω`]];$('#live-checks').innerHTML=checks.map(([pass,text])=>`<div class="check-item ${pass?'':'fail'}">${pass?'✓':'!'} ${text}</div>`).join('');}
const demos={clean:{scenario:'constant',view:'lab',text:'Contribution: compare RLS-VSS with HOLD/TRACK. The clean baseline cuts active duty perturbations by 89.6%, with a small tracking-efficiency trade-off. HOLD keeps PWM running; it freezes the duty command.'},step:{scenario:'irradiance',view:'full',text:'Adaptation: at iteration 250, sunlight falls from 1000 to 700 W/m². Follow confidence, the return to TRACK, and the new operating point. Compare acquisition delays in the table.'},burst:{scenario:'burst',view:'full',text:'SEARCH mechanism: after the controller has held once, a sustained 8 W noise burst lowers confidence. The event-triggered search probes 15 duty values, then hands control back to TRACK. Search power samples are noise-free in the original code; this is a modeling limitation.'},trap:{scenario:'trap',view:'full',text:'Honest limitation: start at duty 0.65 under 1000/600/300 W/m² shading. The full controller can become confident at a local peak and fail to trigger SEARCH. The global reference is an offline evaluation oracle, not information supplied to the controller.'},converter:{text:'Model validity: examine the duty-step transient. The original MPPT comparison assumes instant settling at each iteration. A physical implementation needs a sample period justified by converter dynamics and then a coupled-model or hardware validation.'}};
$$('[data-demo]').forEach(b=>b.onclick=()=>{let id=b.dataset.demo,d=demos[id];$$('[data-demo]').forEach(x=>x.classList.toggle('active',x===b));$('#demo-insight').hidden=false;$('#demo-insight').textContent=d.text;if(id==='converter'){changeView('converter');return}options={...defaults};$('#scenario').value=d.scenario;selectScenario();cursor=id==='clean'?499:id==='step'?250:id==='burst'?210:599;changeView(d.view);});
$('#export-settings').onclick=()=>{if(!completedOptions)return;downloadFile('mppt-experiment.json',JSON.stringify({schema:'mppt-experiment-v2',options:completedOptions,controller:selected,view:['lab','full'].includes(view)?view:'lab',metrics:scores,provenance:lastReference?'Original Python reference trace':'Browser recomputation'},null,2))};
$('#import-settings').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error('Experiment file is too large');let obj=JSON.parse(await f.text());if(obj.schema!=='mppt-experiment-v2'||!obj.options||typeof obj.options!=='object')throw Error('Choose a saved MPPT Lab experiment');let o=obj.options,limits={G:[100,1200],T:[0,70],R:[5,40],D0:[.1,.8],N:[500,600],noise:[0,8],seed:[0,7],G2:[100,1200],T2:[0,70],R2:[5,40],event:[10,590],shade2:[.1,1],shade3:[.1,1],eta:[.00001,.0002],lam:[.4,.98],step:[.001,.03],enter:[.5,.95],exit:[.1,.5],search:[.05,.3],persistence:[10,100]};for(let key of Object.keys(defaults)){if(key==='scenario'){if(!Object.keys(scenarioText).includes(o[key]))throw Error('Invalid scenario')}else {let [lo,hi]=limits[key];if(typeof o[key]!=='number'||!Number.isFinite(o[key])||o[key]<lo||o[key]>hi)throw Error('Invalid '+key)}}if(![500,600].includes(o.N)||!Number.isInteger(o.seed)||!Number.isInteger(o.event)||!Number.isInteger(o.persistence)||o.event>=o.N||o.exit>=o.enter)throw Error('Invalid experiment bounds');options=Object.fromEntries(Object.keys(defaults).map(k=>[k,o[k]]));selected=Number.isInteger(obj.controller)&&obj.controller>=0&&obj.controller<5?obj.controller:4;$('#scenario').value=options.scenario;$('#scenario-desc').textContent=scenarioText[options.scenario];cursor=options.N-1;buildControls();queue();changeView(obj.view==='full'?'full':'lab');$('#demo-insight').hidden=true;$$('[data-demo]').forEach(b=>b.classList.remove('active'));}catch(err){$('#demo-insight').hidden=false;$('#demo-insight').textContent='Experiment not loaded: '+err.message}finally{e.target.value=''}};
function runBoost(){let fields=[['#boost-vin',8,22],['#boost-d0',.1,.8],['#boost-d1',.1,.8],['#boost-r',5,40]],values=[];for(let [id,lo,hi] of fields){let n=Number($(id).value);if(!Number.isFinite(n)||n<lo||n>hi){$('#boost-insight').textContent='Enter values within the indicated input ranges.';return}values.push(n)}boostResult=boostTransient({Vin:values[0],D0:values[1],D1:values[2],R:values[3]});let r=boostResult;$('#boost-metrics').innerHTML=`<div><span>Final equilibrium</span><strong>${r.target.toFixed(2)}<small>V</small></strong></div><div><span>1% settling after step</span><strong>${r.settlingMs===null?'&gt;250':r.settlingMs.toFixed(1)}<small>ms</small></strong></div><div><span>Minimum current</span><strong>${r.minI.toFixed(2)}<small>A</small></strong></div><div><span>CCM model range</span><strong>${r.ccm?'Valid':'Exceeded'}</strong></div>`;$('#boost-insight').textContent=r.ccm?`The averaged current remains positive. Both states ${r.settlingMs===null?'do not settle within 1% during the simulated interval':`settle within 1% after approximately ${r.settlingMs.toFixed(1)} ms`}. This provides a timescale for choosing an update period; it does not validate a physical MPPT sampling rate on its own.`:'The computed inductor current crosses zero. The ideal CCM model is no longer physically valid for this transient. These curves show the mathematical continuation only; reduce the duty step or use a validated DCM model.';drawBoost()}
function drawBoost(){if(view!=='converter'||!boostResult)return;let r=boostResult;graph('#boost-voltage',[{color:'#216b91',data:r.rows.map(x=>[x.t,x.V])},{color:'#96a8b2',dash:[4,4],data:[[0,r.target],[300,r.target]]}],{xMin:0,xMax:300,xLabel:'Time (ms)',cursorAt:50,interactive:false});graph('#boost-current',[{color:'#b47b40',data:r.rows.map(x=>[x.t,x.I])},{color:'#96a8b2',dash:[4,4],data:[[0,r.targetI],[300,r.targetI]]}],{xMin:0,xMax:300,xLabel:'Time (ms)',cursorAt:50,interactive:false})}
$('#boost-run').onclick=runBoost;$('#boost-export').onclick=()=>{if(boostResult)downloadFile('boost-transient.csv','time_ms,duty,output_V,inductor_A\n'+boostResult.rows.map(r=>[r.t,r.D,r.V,r.I].join(',')).join('\n'),'text/csv')};
$('#benchmark-run').onclick=()=>{if(benchWorker)return;$('#benchmark-run').disabled=true;$('#benchmark-export').disabled=true;$('#benchmark-status').textContent='Calculating 100 matched controller runs…';$('#benchmark-progress').value=0;benchWorker=new Worker('benchmark-worker.js',{type:'module'});const finish=()=>{benchWorker.terminate();benchWorker=null;$('#benchmark-run').disabled=false};benchWorker.onmessage=({data:m})=>{if(m.progress){$('#benchmark-progress').value=100*m.progress/m.total;$('#benchmark-status').textContent=`Calculated ${m.progress} of ${m.total} runs.`}if(m.result){benchResult=m.result;$('#benchmark-status').textContent='Complete · 100 runs · all values freshly calculated from the model.';$('#benchmark-export').disabled=false;renderBenchmark();finish()}if(m.error){$('#benchmark-status').textContent='Benchmark failed: '+m.error;finish()}};benchWorker.onerror=()=>{$('#benchmark-status').textContent='Benchmark worker could not run. Reload and retry.';finish()};benchWorker.postMessage(reference)};
function renderBenchmark(){if(!benchResult)return;let id=$('#benchmark-case').value,rows=benchResult.records.filter(r=>r.case===id);$('#benchmark-table').innerHTML=rows.map(r=>`<tr><td>${r.controller}</td><td>${r.eta.toFixed(2)}%${r.seeds>1?' ± '+r.sd.toFixed(2)+' pp':''}</td><td>${r.ss.toFixed(2)}%</td><td>${r.activity.toFixed(3)}</td><td>${r.seeds}</td></tr>`).join('');let best=rows.reduce((a,b)=>b.eta>a.eta?b:a),quiet=rows.reduce((a,b)=>b.activity<a.activity?b:a),f=rows[4],po=rows[0];$('#benchmark-insight').textContent=`Highest mean tracking efficiency: ${best.controller} (${best.eta.toFixed(2)}%). Lowest activity: ${quiet.controller} (${quiet.activity.toFixed(3)}; ties possible). Full controller minus P&O: ${(f.eta-po.eta).toFixed(2)} percentage points. ${id==='trap'?'This is one fixed shaded case, not a new estimate of the archived 52% trap rate.':id==='noise'||id==='burst'?'± is population standard deviation across seeds 0–7. It is not a confidence interval.':'Deterministic run; no seed variation is claimed.'}`;}
$('#benchmark-case').onchange=renderBenchmark;$('#benchmark-export').onclick=()=>{if(benchResult)downloadFile('mppt-benchmark.json',JSON.stringify(benchResult,null,2))};
